// ─── CONFIG ───────────────────────────────────────────────────────
const OWNER_EMAIL_MAP = {
  'Deepti':  'deepti@swissbeauty.in',
  'Ayushi':  'ayushi@swissbeauty.in',
  'Shreya':  'shreya@swissbeauty.in',
  'Sharad':  'sharad@swissbeauty.in',
  'Afzal':   'afzal@swissbeauty.in',
  'Sheetal': 'sheetal@swissbeauty.in',
  'Milan':   'milan@swissbeauty.in',
  'Ananya':  'ananya@swissbeauty.in',
  'Vidushi': 'vidushi@swissbeauty.in',
};
const CC = ['sahil.gaur@swissbeauty.in', 'mohit.goyal@swissbeauty.in'];

// ─── EMAIL BUILDER ────────────────────────────────────────────────
function buildHtml(owner, pending, late, reportDate) {
  const pendingRows = pending.map(r => `
    <tr>
      <td class="td">${r['Product']}</td>
      <td class="td" style="color:#666;font-size:12px">${r['Product Code'] || '—'}</td>
      <td class="td">${r['Brand']}</td>
      <td class="td">${r['Team']}</td>
      <td class="td">${r['Plan Date'] || '—'}</td>
      <td class="td">${r['Given Date']}</td>
      <td class="td" style="color:#c0392b;font-weight:bold">${r['Days Overdue (Given vs Today)']}d overdue</td>
    </tr>`).join('');

  const lateRows = late.map(r => `
    <tr>
      <td class="td">${r['Product']}</td>
      <td class="td" style="color:#666;font-size:12px">${r['Product Code'] || '—'}</td>
      <td class="td">${r['Brand']}</td>
      <td class="td">${r['Team']}</td>
      <td class="td">${r['Plan Date'] || '—'}</td>
      <td class="td">${r['Given Date']}</td>
      <td class="td">${r['Actual Date']}</td>
      <td class="td" style="color:#e67e22;font-weight:bold">+${r['Days Overdue (Given vs Today)']}d late</td>
      <td class="td" style="color:#888">${r['Plan vs Actual (days)'] ? r['Plan vs Actual (days)'] + 'd' : '—'}</td>
    </tr>`).join('');

  const pendingSection = pending.length ? `
    <h3 style="color:#c0392b;margin-top:24px">🔴 Still Not Delivered (${pending.length})</h3>
    <p>These have passed their Given Date and nothing has been delivered yet.</p>
    <table>
      <thead><tr>
        <th>Product</th><th>Code</th><th>Brand</th><th>Team</th>
        <th>Plan Date</th><th>Given Date</th><th>Days Overdue</th>
      </tr></thead>
      <tbody>${pendingRows}</tbody>
    </table>` : '';

  const lateSection = late.length ? `
    <h3 style="color:#e67e22;margin-top:32px">🟠 Delivered Late (${late.length})</h3>
    <p>These were delivered after the Given Date. <em>Plan→Actual</em> shows total days taken from original plan.</p>
    <table>
      <thead><tr>
        <th>Product</th><th>Code</th><th>Brand</th><th>Team</th>
        <th>Plan Date</th><th>Given Date</th><th>Actual Date</th>
        <th>Given→Actual</th><th>Plan→Actual</th>
      </tr></thead>
      <tbody>${lateRows}</tbody>
    </table>` : '';

  return `<!DOCTYPE html><html><head><style>
    body{font-family:Arial,sans-serif;color:#333;font-size:14px}
    h2{color:#1a1a2e} h3{margin-bottom:8px}
    table{border-collapse:collapse;width:100%;margin-top:12px}
    th{background:#1a1a2e;color:#fff;padding:10px 12px;text-align:left;font-size:12px}
    .td{padding:8px 12px;border:1px solid #ddd;vertical-align:top;font-size:13px}
    tr:nth-child(even) .td{background:#f9f9f9}
    .btn{display:inline-block;margin-top:24px;padding:12px 28px;background:#111111 !important;color:#ffffff !important;text-decoration:none !important;border-radius:6px;font-size:14px;font-weight:bold;letter-spacing:0.3px}
    .footer{margin-top:12px;font-size:12px;color:#aaa}
  </style></head><body>
  <h2>⚠️ Weekly TAT Breach Report</h2>
  <p>Hi ${owner},</p>
  <p>Report: <strong>${reportDate}</strong></p>
  ${pendingSection}
  ${lateSection}
  <br>
  <a href="https://docs.google.com/spreadsheets/d/17Zs-ZI6sBFpxszmyiwt4oFzp1MTiqhEE1VtWyxsunv0/edit" target="_blank" style="display:inline-block;margin-top:24px;padding:12px 28px;background:#111111;color:#ffffff;text-decoration:none;border-radius:6px;font-size:14px;font-weight:bold;letter-spacing:0.3px">Open Tracker</a>
  <p class="footer">Automated Report, Every Monday 10 AM · By Swiss Beauty AI team<br>
  Please update the Actual Date in the sheet once delivered.</p>
  </body></html>`;
}

// ─── MAIN ─────────────────────────────────────────────────────────
const allRows = $input.all();

if (!allRows.length || !allRows.some(i => i.json['Product'])) {
  return [{ json: { _skip: true } }];
}

const byOwner = {};
for (const item of allRows) {
  const row = item.json;
  if (!row['Product']) continue;
  const owner = row['Owner'] || 'Unknown';
  if (!byOwner[owner]) byOwner[owner] = { pending: [], late: [] };
  if (row['Type'] === 'Pending (Not Delivered)') byOwner[owner].pending.push(row);
  else byOwner[owner].late.push(row);
}

const reportDate = allRows[0]?.json['Report Date'] || new Date().toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });

return Object.entries(byOwner).map(([owner, { pending, late }]) => {
  const ownerEmail = OWNER_EMAIL_MAP[owner];
  const to = [...(ownerEmail ? [ownerEmail] : []), ...CC].join(', ');
  const total = pending.length + late.length;
  return {
    json: {
      _skip: false,
      to,
      subject: `⚠️ NPD/EPD TAT Report – ${reportDate} · ${owner}: ${pending.length} pending, ${late.length} delivered late`,
      html_body: buildHtml(owner, pending, late, reportDate),
      owner,
      total,
    }
  };
});
